function PlanSummary({plan}: {plan:WorkflowPlan|null}){if(!plan)return <div className="empty-small bordered">当前没有可展示的节点摘要，请在流程页核对计划；实际构建以后台保存的计划及配置为准。</div>;return <div className="plan-summary"><div className="plan-node-list">{plan.nodes.map((node,i)=>{const config=node.config||{};let detail='';if(node.type==='if-else')detail=`${Array.isArray(config.cases)?config.cases.length:0} 个条件分支`;
 if(node.type==='code')detail='代码将由 Dify Sandbox 运行；未在本机执行。';
 if(node.type==='http-request')detail=`${String(config.method||'GET')} ${String(config.url||'未填写 URL')} · 资源请求`;
 if(node.type==='knowledge-retrieval'){const own=config.dataset_source==='node'||config.dataset_source===undefined&&Array.isArray(config.dataset_ids)&&config.dataset_ids.length>0,m=config.reranking_model as Record<string,unknown>|undefined;detail=`${own?`独立 ${Array.isArray(config.dataset_ids)?config.dataset_ids.length:0} 个库`:'继承任务选库'} · Top K ${String(config.top_k||'任务值')} · 阈值 ${config.score_threshold===undefined||config.score_threshold===null?'关闭':String(config.score_threshold)} · ${config.reranking_enable===true?`重排 ${m&&typeof m==='object'?String(m.model||'型号未填'):'配置不完整'}`:'不重排'}`;}
 if(node.type==='iteration')detail=`${config.is_parallel===false?'顺序逐项执行':config.is_parallel===true?`并行逐项执行 · 并发 ${String(config.parallel_nums||'未指定')}`:'执行模式未指定'} · ${config.error_handle_mode==='terminated'?'任一项失败停止整批':'失败策略未适配／未指定'} · ${config.flatten_output===false?'不展开输出':'输出展开未适配／未指定'}`;
 if(node.type==='variable-aggregator')detail=`按列表优先级取第一个存在的变量 · 输出 ${String(config.output_type||'未明确')} · ${Array.isArray(config.variables)?config.variables.map(v=>Array.isArray(v)?v.join('.'):'未明确引用').join(' → '):'未明确候选'}`;
 if(node.type==='llm'){const m=config.model as Record<string,unknown>|undefined;detail=Object.hasOwn(config,'model')?`独立模型 ${m&&typeof m==='object'?String(m.provider||'未填供应商'):''} / ${m&&typeof m==='object'?String(m.name||'未填型号'):'配置不完整'}；完整参数不继承其他模型。`:'继承任务配置中的模型及完整参数。';}
 return <div className="plan-node" key={node.id}><span>{i+1}</span><div><b>{node.title||planTypeNames[node.type]||node.type}</b><small>{planTypeNames[node.type]||node.type}{detail?` · ${detail}`:''}</small>{node.type==='iteration'&&<>{config.is_parallel===true&&<small>并行独立性声明：{config.parallel_safe===true?'已声明，仍需用户复核':'未明确'} · {String(config.parallel_reason||'缺少原因')}。结果按输入索引汇总，失败后已派发项可能仍在执行。</small>}<small>输入：{Array.isArray(config.iterator_selector)?config.iterator_selector.join('.'):'未选择数组'}（{String(config.iterator_input_type||'未声明类型')}）→ 汇总：{String(config.output_type||'未声明类型')}</small><small>{Array.isArray(config.edges)?"内部节点（按实际连接分支执行）：":"每项按顺序执行："}{Array.isArray(config.nodes)?(config.nodes as PlanNode[]).map((child,j)=>`${j+1}. ${child.title||child.id}（${planTypeNames[child.type]||child.type}）`).join(' → '):'未设置内部节点'}</small><small>内部使用 item／index；输出保留重复项并按输入索引排序。内部模型逐项使用独立或继承的配置调用，不读取 Chatflow 历史；批量费用尚无全任务硬上限。</small></>}</div></div>})}</div>{plan.edges.length>0&&<div className="plan-edges">流程连接：{plan.edges.map(e=>`${e.source} → ${e.target}${e.source_handle?`（${e.source_handle}）`:''}`).join('，')}</div>}</div>}
async function api<T>(path:string,init:RequestInit={}):Promise<T>{const windowed=(!init.method||init.method==='GET')&&/^\/tasks\/[^/?]+$/.test(path);const target=windowed?`${path}?workspace_view=compact-v2`:path;const r=await fetch(`${import.meta.env.VITE_API_BASE||'/api'}${target}`,windowed?{...init,cache:'no-store'}:init);if(!r.ok){let m=`请求失败（HTTP ${r.status}）`;try{const j=await r.json();if(typeof j.detail==='string')m=j.detail;}catch{}throw Error(m);}if(r.status===204)return undefined as T;if((r.headers.get('content-type')||'').includes('json')){const value=await r.json();if(windowed)validateWorkspaceView(value,'compact-v2');if(path==='/settings'){const source=r.headers.get('X-Sierra-Settings-Source');if(source!==null){if(!/^[a-f0-9]{64}$/.test(source)||!value||typeof value!=='object'||Array.isArray(value))throw Error('执行规则读取来源无法核对，未采用返回值。');return {...value,source_token:source} as T}}return value as T}return r.blob() as T;}
